import type { Argv, ArgumentsCamelCase, CommandModule } from 'yargs'
import { cwd } from 'process'
import * as fs from 'fs'
import { validateWorkingDir } from '../../util'
import { logger } from '../../logger'
import { createTelemetryClient } from '../../telemetry'
import { Orchestrator, Project } from '@servicenow/sdk-api'
import { NowConfig } from '@servicenow/sdk-build-core'
import { credentialProvider } from '../../auth'

interface Arguments {
    script: string
    cwd: string
    auth: string | undefined
}

export const run: CommandModule<unknown, Arguments> = {
    command: 'run [script]',
    describe: 'Run a script defined in the project configuration',
    builder: (yargs: Argv) => {
        return yargs
            .positional('script', {
                describe: 'Name of the script to run',
                type: 'string',
            })
            .demandOption('script')
            .positional('cwd', {
                describe: 'The working directory to run the script in',
                default: cwd(),
                type: 'string',
            })
            .option('auth', {
                describe: 'Credential alias to use for authentication with instance',
                type: 'string',
                alias: 'a',
            })
    },
    handler: async (args: ArgumentsCamelCase<Arguments>): Promise<void> => {
        const credential = await credentialProvider(args.auth)
        const telemetryClient = createTelemetryClient(fs, __dirname, credential.getUrl())
        const telemetryTimer = telemetryClient.startTimerEvent('run')

        try {
            const workingDir = validateWorkingDir(args.cwd)

            const config = NowConfig.parseFromDirectory(workingDir, fs, logger)

            // Listen for SIGINT (Ctrl+C) to send telemetry for long-running scripts
            process.on('SIGINT', async () => {
                await telemetryClient.sendEvent(
                    telemetryTimer.end({
                        appInfo: { scopeId: config.scopeId },
                    })
                )
                process.exit(0)
            })

            const project = new Project({ config, fileSystem: fs, rootDir: workingDir, logger, telemetryClient })

            const orchestrator = new Orchestrator(project, credential)

            await orchestrator.run({ script: args.script })
        } catch (error) {
            logger.error('Error running script:', error)

            process.exitCode = 1 // set exit code to 1 to indicate failure for CI
        }
    },
}
